const LANDING = "<!doctype html>\n<html lang=\"en\" data-theme=\"dark\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"description\" content=\"Aftergraph — infrastructure for verifiable intelligent systems.\">\n<title>Aftergraph — Infrastructure for verifiable intelligent systems</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' rx='6' fill='%23080c14'/><path d='M16 5l9 5v12l-9 5-9-5V10z' fill='none' stroke='%2342c7e8' stroke-width='2'/></svg>\">\n<style>\n:root{color-scheme:dark;--canvas:#080c14;--canvas-raised:#0e1630;--surface:rgba(14,22,48,.72);--surface-strong:rgba(20,31,64,.92);--text:#f5f7fa;--muted:#8993a4;--subtle:#5a6474;--border:rgba(137,147,164,.2);--border-strong:rgba(66,199,232,.4);--control:#42c7e8;--control-soft:rgba(66,199,232,.14);--evidence:#24c4ad;--evidence-soft:rgba(36,196,173,.14);--authority:#7759e8;--authority-soft:rgba(119,89,232,.16);--decision:#f0a64a;--system:#4c8bd8;--radius:12px;--ease:cubic-bezier(.16,1,.3,1)}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--canvas);color:var(--text);font-family:Inter,-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;line-height:1.6;-webkit-font-smoothing:antialiased}body:before{content:\"\";position:fixed;inset:0;z-index:-2;background-image:linear-gradient(rgba(66,199,232,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(66,199,232,.035) 1px,transparent 1px);background-size:64px 64px;mask-image:linear-gradient(to bottom,black,transparent 76%);pointer-events:none}body:after{content:\"\";position:fixed;inset:0;z-index:-1;background:radial-gradient(circle at var(--px,50%) var(--py,18%),rgba(66,199,232,.08),transparent 28rem);pointer-events:none}a{color:var(--control);text-decoration:none}a:hover{color:#a9e8f6}.shell{width:min(1180px,calc(100% - 48px));margin:auto}.nav{position:sticky;top:0;z-index:20;display:flex;align-items:center;justify-content:space-between;min-height:68px;background:rgba(8,12,20,.84);backdrop-filter:blur(16px);border-bottom:1px solid rgba(137,147,164,.14)}.brand{font-size:14px;font-weight:700;letter-spacing:.08em;color:var(--text)}.brand i{font-style:normal;color:var(--control)}.nav-links{display:flex;align-items:center;gap:24px}.nav-links a{color:var(--muted);font-size:13px;font-weight:500}.nav-links a:hover{color:var(--text)}.nav-links .launch{color:var(--canvas);background:var(--control);padding:8px 14px;border-radius:8px;font-weight:700}.nav-links .launch:hover{color:var(--canvas);background:#8fe0f5}.hero{position:relative;display:grid;grid-template-columns:minmax(0,1.02fr) minmax(360px,.98fr);gap:56px;align-items:center;min-height:calc(100vh - 68px);padding:88px 0 80px;overflow:hidden}.hero-copy{position:relative;z-index:1}.eyebrow,.section-kicker{margin:0 0 16px;color:var(--control);font:500 11px/1.4 \"JetBrains Mono\",ui-monospace,monospace;letter-spacing:.08em;text-transform:uppercase}.hero h1{max-width:720px;margin:0;font-size:clamp(44px,6.2vw,82px);line-height:.98;letter-spacing:-.065em;font-weight:500}.hero-lede{max-width:600px;margin:28px 0 34px;color:#aeb7c5;font-size:18px;line-height:1.65}.actions{display:flex;flex-wrap:wrap;gap:10px}.button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:10px 16px;border:1px solid var(--border);border-radius:8px;color:var(--text);font-size:14px;font-weight:650;transition:transform 180ms var(--ease),border-color 180ms var(--ease),background 180ms var(--ease)}.button:hover{transform:translateY(-2px);border-color:var(--border-strong);color:var(--text);background:rgba(66,199,232,.07)}.button.primary{border-color:var(--control);background:var(--control);color:var(--canvas)}.button.primary:hover{background:#8fe0f5;color:var(--canvas)}.field{position:relative;min-height:470px;display:grid;place-items:center}.field:before{content:\"\";position:absolute;width:78%;aspect-ratio:1;border:1px solid rgba(66,199,232,.18);border-radius:50%;box-shadow:0 0 90px rgba(66,199,232,.07),inset 0 0 70px rgba(36,196,173,.04)}.field svg{position:relative;width:100%;height:auto;overflow:visible}.field .trace{fill:none;stroke:rgba(66,199,232,.3);stroke-width:1.2;stroke-dasharray:5 7;animation:trace 8s linear infinite}.field .node{fill:var(--canvas-raised);stroke:var(--control);stroke-width:1.5}.field .node.authority{stroke:var(--authority)}.field .node.evidence{stroke:var(--evidence)}.field .node.verified{stroke:var(--evidence);fill:rgba(36,196,173,.18)}.field text{fill:var(--muted);font:500 11px \"JetBrains Mono\",ui-monospace,monospace;text-anchor:middle}.field text.strong{fill:var(--text)}@keyframes trace{to{stroke-dashoffset:-96}}.trace-caption{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);width:max-content;color:var(--subtle);font:11px \"JetBrains Mono\",ui-monospace,monospace}.status-line{display:flex;flex-wrap:wrap;gap:16px;padding:16px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border);color:var(--muted);font-size:12px}.status-line span{display:inline-flex;align-items:center;gap:7px}.status-line b{color:var(--text);font-weight:500}.dot{width:7px;height:7px;border-radius:50%;background:var(--evidence);box-shadow:0 0 12px rgba(36,196,173,.8)}.section{padding:112px 0}.section-heading{display:grid;grid-template-columns:minmax(220px,.65fr) minmax(0,1.35fr);gap:40px;align-items:start;margin-bottom:48px}.section h2{max-width:700px;margin:0;font-size:clamp(32px,4vw,54px);line-height:1.02;letter-spacing:-.055em;font-weight:500}.section-intro{max-width:590px;margin:0;color:var(--muted);font-size:16px}.lifecycle{display:grid;grid-template-columns:repeat(7,1fr);gap:0;border-block:1px solid var(--border)}.lifecycle-step{position:relative;min-height:126px;padding:22px 14px 20px;border-right:1px solid var(--border)}.lifecycle-step:last-child{border-right:0}.lifecycle-step:after{content:\"→\";position:absolute;right:-8px;top:50%;z-index:1;color:var(--control);background:var(--canvas);transform:translateY(-50%);font-size:16px}.lifecycle-step:last-child:after{display:none}.lifecycle-step small{display:block;margin-bottom:26px;color:var(--subtle);font:11px \"JetBrains Mono\",ui-monospace,monospace}.lifecycle-step strong{font-size:15px;font-weight:600}.lifecycle-step[data-kind=authority] strong{color:#a38ff4}.lifecycle-step[data-kind=evidence] strong,.lifecycle-step[data-kind=verified] strong{color:var(--evidence)}.layers{display:grid;gap:14px}.layer{display:grid;grid-template-columns:220px minmax(0,1fr);gap:28px;padding:26px 0;border-top:1px solid var(--border)}.layer:last-child{border-bottom:1px solid var(--border)}.layer h3{margin:0;font-size:20px;font-weight:550}.layer h3 span{display:block;margin-top:8px;font:11px \"JetBrains Mono\",ui-monospace,monospace;color:var(--subtle)}.layer p{max-width:610px;margin:0 0 18px;color:var(--muted);font-size:15px}.layer-links{display:flex;flex-wrap:wrap;gap:8px}.layer-links a{padding:7px 10px;border:1px solid var(--border);border-radius:7px;color:var(--text);font-size:13px}.layer-links a:hover{border-color:var(--border-strong);background:var(--control-soft)}.layer.institution h3{color:#a38ff4}.layer.execution h3{color:var(--control)}.layer.evidence h3{color:var(--evidence)}.maturity{display:grid;grid-template-columns:1.35fr .65fr;gap:14px}.surface{padding:26px;border:1px solid var(--border);border-radius:var(--radius);background:rgba(14,22,48,.42)}.surface.featured{border-color:rgba(66,199,232,.42);background:linear-gradient(130deg,rgba(66,199,232,.1),rgba(14,22,48,.48))}.surface h3{margin:0 0 8px;font-size:21px;font-weight:600}.surface p{margin:0;color:var(--muted);font-size:14px}.tag{display:inline-flex;margin-top:18px;padding:4px 8px;border:1px solid rgba(240,166,74,.38);border-radius:6px;color:var(--decision);font:11px \"JetBrains Mono\",ui-monospace,monospace}.evidence-grid{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--border);border-bottom:1px solid var(--border)}.evidence-cell{min-height:160px;padding:22px 18px;border-right:1px solid var(--border)}.evidence-cell:last-child{border-right:0}.evidence-cell h3{margin:0 0 14px;font-size:15px;font-weight:600}.evidence-cell p{margin:0;color:var(--muted);font-size:13px}.principles{display:grid;grid-template-columns:repeat(5,1fr);border-top:1px solid var(--border)}.principle{padding:22px 16px 0;border-right:1px solid var(--border)}.principle:last-child{border-right:0}.principle strong{display:block;min-height:44px;font-size:15px;font-weight:600}.principle p{margin:12px 0 0;color:var(--muted);font-size:13px}.rule{margin-top:34px;padding:16px 18px;border-left:2px solid var(--evidence);background:var(--evidence-soft);color:#a9dcd4;font-size:14px}.footer{display:grid;grid-template-columns:1.5fr repeat(3,1fr);gap:32px;padding:64px 0 96px;border-top:1px solid var(--border)}.footer p{max-width:280px;margin:14px 0 0;color:var(--muted);font-size:13px}.footer h3{margin:0 0 14px;color:var(--subtle);font:11px \"JetBrains Mono\",ui-monospace,monospace;letter-spacing:.08em;text-transform:uppercase}.footer a{display:block;margin:0 0 9px;color:var(--muted);font-size:13px}.footer a:hover{color:var(--text)}:focus-visible{outline:2px solid var(--control);outline-offset:3px;border-radius:4px}@media(max-width:900px){.hero{grid-template-columns:1fr;min-height:auto;padding-top:72px}.field{min-height:360px}.section-heading{grid-template-columns:1fr;gap:18px}.lifecycle{grid-template-columns:1fr}.lifecycle-step{min-height:auto;padding:16px 18px;border-right:0;border-bottom:1px solid var(--border)}.lifecycle-step:last-child{border-bottom:0}.lifecycle-step:after{right:auto;left:50%;top:auto;bottom:-9px;transform:translateX(-50%) rotate(90deg)}.lifecycle-step small{display:inline-block;margin:0 12px 0 0}.maturity{grid-template-columns:1fr}.evidence-grid,.principles{grid-template-columns:1fr 1fr}.evidence-cell:nth-child(2){border-right:0}.evidence-cell:nth-child(-n+2){border-bottom:1px solid var(--border)}.principle{min-height:130px;border-bottom:1px solid var(--border)}.principle:nth-child(2n){border-right:0}.footer{grid-template-columns:1.4fr 1fr 1fr}}\n@media(max-width:640px){.shell{width:min(100% - 32px,1180px)}.nav{min-height:60px}.nav-links{gap:12px}.nav-links a:not(.launch){display:none}.hero h1{font-size:clamp(40px,13vw,64px)}.hero-lede{font-size:16px}.field{min-height:290px}.field:before{width:90%}.trace-caption{font-size:9px}.section{padding:76px 0}.evidence-grid,.principles{grid-template-columns:1fr}.evidence-cell,.principle{border-right:0;border-bottom:1px solid var(--border)}.evidence-cell:last-child,.principle:last-child{border-bottom:0}.layer{grid-template-columns:1fr;gap:12px}.footer{grid-template-columns:1fr 1fr;padding-bottom:64px}}\n@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.field .trace{animation:none}.button{transition:none}.button:hover{transform:none}}\n</style>\n<link rel=\"icon\" type=\"image/svg+xml\" href=\"/favicon.ico\">\n<meta property=\"og:site_name\" content=\"Aftergraph\">\n<meta property=\"og:title\" content=\"Aftergraph — Verifiable Intelligent Systems\">\n<meta property=\"og:description\" content=\"Infrastructure and open research for verifiable intelligent systems: missions, authority, durable execution, evidence, verification and agentic institutions.\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:url\" content=\"https://aftergraph.org/\">\n<meta property=\"og:image\" content=\"https://aftergraph.org/og-image.svg\">\n<meta name=\"twitter:card\" content=\"summary\">\n<meta name=\"twitter:title\" content=\"Aftergraph\">\n<meta name=\"twitter:description\" content=\"Infrastructure and open research for verifiable intelligent systems.\">\n<script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"Organization\",\"name\":\"Aftergraph\",\"url\":\"https://aftergraph.org\",\"description\":\"Infrastructure and open research for verifiable intelligent systems: missions, authority, durable execution, evidence, verification and agentic institutions.\",\"sameAs\":[\"https://github.com/Aftergraph\"]}</script>\n</head>\n<body>\n<nav class=\"nav\" aria-label=\"Primary navigation\"><div class=\"shell\" style=\"display:flex;align-items:center;justify-content:space-between;width:100%\"><a class=\"brand\" href=\"/\" aria-label=\"Aftergraph home\">AFTERGRAPH<i>.</i></a><div class=\"nav-links\"><a href=\"#platform\">Platform</a><a href=\"#research\">Research</a><a href=\"https://docs.aftergraph.org\" target=\"_blank\" rel=\"noopener\">Docs</a><a href=\"#trust\">Trust</a><a class=\"launch\" href=\"/launch\">Launch</a></div></div></nav>\n<main>\n<header class=\"hero shell\" id=\"top\">\n<div class=\"hero-copy\"><p class=\"eyebrow\">Aftergraph system boot</p><h1>Infrastructure for verifiable intelligent systems.</h1><p class=\"hero-lede\">Bound missions. Scoped authority. Durable execution. Evidence that can be checked independently.</p><div class=\"actions\"><a class=\"button primary\" href=\"#platform\">Explore the platform</a><a class=\"button\" href=\"https://docs.aftergraph.org\" target=\"_blank\" rel=\"noopener\">Read the docs</a><a class=\"button\" href=\"/launch\">Launch system</a></div></div>\n<div class=\"field\" aria-label=\"Aftergraph lifecycle field\"><svg viewBox=\"0 0 560 460\" role=\"img\" aria-labelledby=\"field-title field-desc\"><title id=\"field-title\">Aftergraph verified intelligent system lifecycle</title><desc id=\"field-desc\">Intent becomes a mission, receives authority, executes, emits evidence, and reaches a verified outcome.</desc><path class=\"trace\" d=\"M74 230 C130 90 215 76 280 230 S430 370 486 230\"/><path class=\"trace\" d=\"M74 230 C145 350 210 360 280 230 S418 110 486 230\"/><circle class=\"node\" cx=\"74\" cy=\"230\" r=\"26\"/><circle class=\"node\" cx=\"177\" cy=\"124\" r=\"26\"/><circle class=\"node authority\" cx=\"280\" cy=\"230\" r=\"31\"/><circle class=\"node\" cx=\"383\" cy=\"336\" r=\"26\"/><circle class=\"node evidence\" cx=\"383\" cy=\"124\" r=\"26\"/><circle class=\"node verified\" cx=\"486\" cy=\"230\" r=\"30\"/><text x=\"74\" y=\"235\">Intent</text><text x=\"177\" y=\"129\">Mission</text><text x=\"280\" y=\"235\" class=\"strong\">Authority</text><text x=\"383\" y=\"341\">Execution</text><text x=\"383\" y=\"129\">Evidence</text><text x=\"486\" y=\"235\" class=\"strong\">Verified</text></svg><span class=\"trace-caption\">intent → mission → authority → execution → evidence → verification</span></div>\n</header>\n<div class=\"status-line shell\" aria-label=\"Public system signals\"><span><i class=\"dot\" aria-hidden=\"true\"></i><b>Public surface available</b></span><span>8 public repositories</span><span><b>WORKS</b> most mature runtime surface</span><span>Research evidence is never runtime authority</span></div>\n<section class=\"section shell\" id=\"thesis\"><div class=\"section-heading\"><p class=\"section-kicker\">01 / Thesis</p><div><h2>From intent to verified outcome.</h2><p class=\"section-intro\">An agent acts under a mission. It spends only what an authority allows. Every action leaves an evidence trail. A verifier can check the outcome.</p></div></div><ol class=\"lifecycle\" aria-label=\"Verified intelligent system lifecycle\"><li class=\"lifecycle-step\" data-kind=\"intent\"><small>01</small><strong>Intent</strong></li><li class=\"lifecycle-step\" data-kind=\"mission\"><small>02</small><strong>Mission</strong></li><li class=\"lifecycle-step\" data-kind=\"authority\"><small>03</small><strong>Authority</strong></li><li class=\"lifecycle-step\" data-kind=\"execution\"><small>04</small><strong>Execution</strong></li><li class=\"lifecycle-step\" data-kind=\"evidence\"><small>05</small><strong>Evidence</strong></li><li class=\"lifecycle-step\" data-kind=\"verification\"><small>06</small><strong>Verification</strong></li><li class=\"lifecycle-step\" data-kind=\"verified\"><small>07</small><strong>Verified outcome</strong></li></ol></section>\n<section class=\"section shell\" id=\"platform\"><div class=\"section-heading\"><p class=\"section-kicker\">02 / Platform</p><div><h2>One system. Three control layers.</h2><p class=\"section-intro\">Aftergraph connects institutional semantics, control and execution, and the evidence plane. The relationships matter more than a wall of product cards.</p></div></div><div class=\"layers\"><article class=\"layer institution\"><h3>Intelligence / Institution<span>mission semantics · authority · delegation</span></h3><div><p>Define what an intelligent system is allowed to do, why it is doing it, and how authority attenuates through delegation.</p><div class=\"layer-links\"><a href=\"https://github.com/Aftergraph/aie\">AIE</a><a href=\"https://github.com/Aftergraph/after-graph-governance\">Governance</a><a href=\"https://docs.aftergraph.org\">Knowledge Plane</a></div></div></article><article class=\"layer execution\"><h3>Control &amp; execution<span>durable work · state · recovery</span></h3><div><p>Turn a bounded mission into durable work with leases, budgets, worker state, recovery and operational surfaces.</p><div class=\"layer-links\"><a href=\"https://github.com/Aftergraph/works-execution\">WORKS Execution</a><a href=\"https://github.com/Aftergraph/work-intelligence-v2\">Work Intelligence</a><a href=\"https://github.com/Aftergraph/trust-gateway\">Trust Gateway</a><a href=\"https://github.com/Aftergraph/studio\">Studio</a></div></div></article><article class=\"layer evidence\"><h3>Evidence &amp; knowledge<span>claims · provenance · verification</span></h3><div><p>Make outcomes inspectable. Separate self-report from evidence, evidence from verification, and research from runtime authority.</p><div class=\"layer-links\"><a href=\"https://github.com/Aftergraph/sentinel\">Sentinel</a><a href=\"https://github.com/Aftergraph/intelligence-systems-research\">Research</a><a href=\"https://docs.aftergraph.org\">Evidence plane</a></div></div></article></div></section>\n<section class=\"section shell\" id=\"systems\"><div class=\"section-heading\"><p class=\"section-kicker\">03 / Systems</p><div><h2>Built, honestly labelled.</h2><p class=\"section-intro\">WORKS remains the dominant runtime surface because it is furthest along. Research, prototypes and production behavior stay visibly distinct.</p></div></div><div class=\"maturity\"><article class=\"surface featured\"><h3>WORKS Execution</h3><p>Durable execution plane for autonomous work — missions, WorkGraph scheduling, workers, leases, budgets, recovery and execution evidence.</p><span class=\"tag\">prototype · v0.3.6</span></article><article class=\"surface\"><h3>Work Intelligence</h3><p>Source-neutral observations become structured, attributable WorkItems.</p><span class=\"tag\">prototype</span></article></div></section>\n<section class=\"section shell\" id=\"research\"><div class=\"section-heading\"><p class=\"section-kicker\">04 / Evidence</p><div><h2>Research is not runtime authority.</h2><p class=\"section-intro\">A claim can be useful without being promoted. Every surface tells you what kind of evidence you are looking at.</p></div></div><div class=\"evidence-grid\"><article class=\"evidence-cell\"><h3>Research result</h3><p>SPEC-001 and MISSION-Bench make research claims reproducible and inspectable.</p></article><article class=\"evidence-cell\"><h3>Specification / standard proposal</h3><p>Governance defines boundaries and contracts without silently becoming implementation.</p></article><article class=\"evidence-cell\"><h3>Implementation / runtime</h3><p>WORKS, Trust Gateway and other repos expose what is actually built.</p></article><article class=\"evidence-cell\"><h3>Verified production behavior</h3><p>Only independent evidence can justify a stronger operational claim.</p></article></div><p class=\"rule\">Research evidence can justify a promotion decision; it is never runtime authority by itself.</p></section>\n<section class=\"section shell\" id=\"trust\"><div class=\"section-heading\"><p class=\"section-kicker\">05 / Why Aftergraph</p><div><h2>Complete is not verified.</h2><p class=\"section-intro\">The system is designed around durable principles instead of confidence theatre.</p></div></div><div class=\"principles\"><article class=\"principle\"><strong>Complete != Verified</strong><p>Finished work still needs independent checking.</p></article><article class=\"principle\"><strong>Purpose-bound authority</strong><p>Permissions are scoped to the mission.</p></article><article class=\"principle\"><strong>Durable execution and recovery</strong><p>Long work survives interruption.</p></article><article class=\"principle\"><strong>Deterministic evidence gates</strong><p>Claims point to inspectable artifacts.</p></article><article class=\"principle\"><strong>Cost per verified outcome</strong><p>Efficiency is measured against what was proven.</p></article></div></section>\n<section class=\"section shell\" id=\"launch\"><div class=\"section-heading\"><p class=\"section-kicker\">06 / Launch</p><div><h2>Enter the system, not another brochure.</h2><p class=\"section-intro\">Search the ecosystem by intent. Find what you can build, operate, verify and research from one command surface.</p><a class=\"button primary\" href=\"/launch\">Open Mission Control</a></div></div></section>\n</main>\n<footer class=\"footer shell\"><div><a class=\"brand\" href=\"/\">AFTERGRAPH<i>.</i></a><p>Infrastructure and open research for verifiable intelligent systems.</p></div><div><h3>Build</h3><a href=\"https://github.com/Aftergraph/works-execution\">WORKS</a><a href=\"https://github.com/Aftergraph/work-intelligence-v2\">Work Intelligence</a><a href=\"https://docs.aftergraph.org\">Knowledge Plane</a></div><div><h3>Research</h3><a href=\"https://github.com/Aftergraph/intelligence-systems-research\">Research</a><a href=\"https://github.com/Aftergraph/sentinel\">Sentinel</a><a href=\"https://github.com/Aftergraph/model-registry\">Model Registry</a></div><div><h3>Trust</h3><a href=\"https://github.com/Aftergraph/trust-gateway\">Trust Gateway</a><a href=\"https://github.com/Aftergraph/after-graph-governance\">Governance</a><a href=\"https://github.com/Aftergraph\">GitHub organization</a><a href=\"/status\">System status</a></div></footer>\n<script>\nconst root=document.documentElement;\ndocument.addEventListener('pointermove',event=>{root.style.setProperty('--px',`${(event.clientX/window.innerWidth)*100}%`);root.style.setProperty('--py',`${(event.clientY/window.innerHeight)*100}%`);},{passive:true});\n</script>\n</body>\n</html>\n";
const LAUNCH = "<!doctype html>\n<html lang=\"en\" data-theme=\"dark\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"description\" content=\"Aftergraph Mission Control — search systems, evidence, research and repositories.\">\n<title>Mission Control — Aftergraph</title>\n<link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' rx='6' fill='%23080c14'/><path d='M16 5l9 5v12l-9 5-9-5V10z' fill='none' stroke='%2342c7e8' stroke-width='2'/></svg>\">\n<style>\n:root{color-scheme:dark;--canvas:#080c14;--raised:#0e1630;--surface:rgba(14,22,48,.82);--text:#f5f7fa;--muted:#8993a4;--subtle:#5a6474;--border:rgba(137,147,164,.22);--control:#42c7e8;--control-soft:rgba(66,199,232,.12);--evidence:#24c4ad;--authority:#7759e8;--decision:#f0a64a;--system:#4c8bd8;--ease:cubic-bezier(.16,1,.3,1)}\n*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--canvas)}body{color:var(--text);font:15px/1.6 Inter,-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;-webkit-font-smoothing:antialiased;background-image:linear-gradient(rgba(66,199,232,.03) 1px,transparent 1px),linear-gradient(90deg,rgba(66,199,232,.03) 1px,transparent 1px);background-size:64px 64px}a{color:inherit;text-decoration:none}button,input{font:inherit}.frame{width:min(1080px,calc(100% - 40px));margin:0 auto;padding:40px 0 76px}.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:34px}.brand{color:var(--control);font-size:13px;font-weight:700;letter-spacing:.08em}.topbar .back{color:var(--muted);font-size:13px}.topbar .back:hover{color:var(--text)}.intro{display:flex;align-items:end;justify-content:space-between;gap:32px;margin-bottom:28px}.intro h1{margin:0;font-size:clamp(36px,6vw,66px);font-weight:500;line-height:.98;letter-spacing:-.065em}.intro p{max-width:350px;margin:0;color:var(--muted);font-size:14px}.shell{position:relative;overflow:hidden;border:1px solid var(--border);border-radius:16px;background:linear-gradient(145deg,rgba(20,31,64,.9),rgba(14,22,48,.76));box-shadow:0 24px 80px rgba(0,0,0,.42)}.shell:before{content:\"\";position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 75% 0,rgba(66,199,232,.12),transparent 28rem)}.search{position:relative;z-index:1;display:flex;align-items:center;gap:12px;padding:18px 22px;border-bottom:1px solid var(--border)}.search-mark{color:var(--control);font:16px \"JetBrains Mono\",ui-monospace,monospace}.search input{width:100%;min-height:32px;padding:0;border:0;outline:0;background:transparent;color:var(--text);font-size:19px}.search input::placeholder{color:var(--subtle)}.search kbd,.hint kbd{padding:2px 6px;border:1px solid var(--border);border-radius:5px;color:var(--muted);font:11px \"JetBrains Mono\",ui-monospace,monospace;white-space:nowrap}.hint{position:relative;z-index:1;display:flex;align-items:center;gap:14px;padding:10px 22px;border-bottom:1px solid rgba(137,147,164,.13);color:var(--subtle);font-size:12px}.hint .spacer{flex:1}.overview{position:relative;z-index:1;display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:18px 22px;border-bottom:1px solid rgba(137,147,164,.13)}.signal{padding:12px 14px;border:1px solid rgba(137,147,164,.16);border-radius:9px;background:rgba(8,12,20,.2)}.signal small{display:block;margin-bottom:4px;color:var(--subtle);font:10px \"JetBrains Mono\",ui-monospace,monospace;text-transform:uppercase;letter-spacing:.08em}.signal strong{font-size:14px;font-weight:600}.signal a{color:var(--text)}.signal a:hover{color:var(--control)}.pulse{display:inline-block;width:7px;height:7px;margin-right:6px;border-radius:50%;background:var(--evidence);box-shadow:0 0 10px rgba(36,196,173,.7)}.results{position:relative;z-index:1;max-height:560px;overflow-y:auto;padding:10px 0 16px}.group{padding:16px 22px 7px;color:var(--subtle);font:11px \"JetBrains Mono\",ui-monospace,monospace;letter-spacing:.08em;text-transform:uppercase}.option{display:flex;align-items:center;gap:14px;width:100%;min-height:64px;padding:11px 22px;border-left:3px solid transparent;transition:background 180ms var(--ease),border-color 180ms var(--ease),transform 180ms var(--ease)}.option:hover,.option[aria-selected=true]{background:var(--control-soft);border-left-color:var(--control)}.option:focus-visible{outline:2px solid var(--control);outline-offset:-3px}.option-icon{display:grid;place-items:center;flex:0 0 30px;width:30px;height:30px;border:1px solid var(--border);border-radius:8px;color:var(--control);font:12px \"JetBrains Mono\",ui-monospace,monospace}.option-copy{min-width:0}.option-name{display:block;font-size:15px;font-weight:650}.option-purpose{display:block;overflow:hidden;color:var(--muted);font-size:13px;text-overflow:ellipsis;white-space:nowrap}.option-meta{display:flex;align-items:center;gap:8px;margin-left:auto;flex-shrink:0}.badge{padding:3px 7px;border:1px solid rgba(240,166,74,.36);border-radius:5px;color:var(--decision);font:10px \"JetBrains Mono\",ui-monospace,monospace;text-transform:lowercase}.badge.research{border-color:rgba(137,147,164,.32);color:var(--muted)}.badge.production{border-color:rgba(36,196,173,.38);color:var(--evidence)}.badge.docs{border-color:rgba(76,139,216,.38);color:#8ab7ef}.arrow{color:var(--control);font-size:17px;opacity:0;transform:translateX(-4px);transition:opacity 180ms var(--ease),transform 180ms var(--ease)}.option[aria-selected=true] .arrow,.option:hover .arrow{opacity:1;transform:none}.empty{padding:48px 22px;text-align:center;color:var(--muted)}.empty strong{display:block;margin-bottom:7px;color:var(--text);font-weight:600}.footnote{margin-top:14px;color:var(--subtle);font-size:12px}.footnote a{color:var(--muted)}.footnote a:hover{color:var(--control)}:focus-visible{outline:2px solid var(--control);outline-offset:3px;border-radius:4px}@media(max-width:680px){.frame{width:min(100% - 24px,1080px);padding-top:24px}.intro{display:block}.intro p{margin-top:18px}.shell{border-radius:12px}.search{padding:16px}.search kbd{display:none}.hint{gap:9px;padding:10px 16px;font-size:11px}.overview{grid-template-columns:1fr;padding:14px 16px}.results{max-height:none}.group{padding-left:16px}.option{min-height:68px;padding:12px 16px}.option-purpose{white-space:normal}.option-meta{display:none}}\n@media(prefers-reduced-motion:reduce){.option,.arrow{transition:none}}\n</style>\n<link rel=\"icon\" type=\"image/svg+xml\" href=\"/favicon.ico\">\n<meta property=\"og:site_name\" content=\"Aftergraph\">\n<meta property=\"og:title\" content=\"Launcher — Aftergraph\">\n<meta property=\"og:description\" content=\"System launcher and command palette for all Aftergraph destinations.\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:url\" content=\"https://aftergraph.org/launch\">\n<meta property=\"og:image\" content=\"https://aftergraph.org/og-image.svg\">\n</head>\n<body>\n<main class=\"frame\" id=\"launcher-shell\" tabindex=\"-1\">\n<header class=\"topbar\"><a class=\"brand\" href=\"/\">AFTERGRAPH /</a><a class=\"back\" href=\"/\">Back to the system overview</a></header>\n<section class=\"intro\" aria-labelledby=\"title\"><h1 id=\"title\">Mission Control</h1><p>One command surface for what you can build, operate, verify and research across Aftergraph.</p></section>\n<section class=\"shell\" aria-label=\"Aftergraph command surface\">\n<div class=\"search\"><span class=\"search-mark\" aria-hidden=\"true\">⌕</span><label for=\"q\" class=\"sr-only\">Search Aftergraph destinations</label><input id=\"q\" type=\"search\" aria-label=\"Search Aftergraph destinations\" aria-controls=\"results\" placeholder=\"Search systems, missions, evidence, research…\" autocomplete=\"off\"><kbd>/</kbd></div>\n<div class=\"hint\"><span><kbd>↑</kbd><kbd>↓</kbd> navigate</span><span><kbd>Enter</kbd> open</span><span><kbd>Esc</kbd> clear</span><span class=\"spacer\"></span><span>maturity-labelled</span></div>\n<div class=\"overview\" aria-label=\"Mission Control overview\"><div class=\"signal\"><small>System surface</small><strong><span class=\"pulse\" aria-hidden=\"true\"></span>Public routes available</strong></div><div class=\"signal\"><small>Recommended path</small><strong><a href=\"https://docs.aftergraph.org\">Start with the Knowledge Plane</a></strong></div><div class=\"signal\"><small>Evidence rule</small><strong>Complete is not verified</strong></div></div>\n<div id=\"results\" class=\"results\" role=\"listbox\" aria-label=\"Aftergraph destinations\" aria-live=\"polite\"></div>\n</section>\n<p class=\"footnote\">Esc clears the query. All destinations open their declared public surface. <a href=\"/status\">Inspect system status</a>.</p>\n</main>\n<script>\nconst ITEMS=[\n{group:'Build',name:'WORKS Execution',purpose:'Durable mission execution, workers, leases, budgets and recovery.',url:'https://github.com/Aftergraph/works-execution',maturity:'prototype',type:'product',icon:'W'},\n{group:'Build',name:'Work Intelligence',purpose:'Source-neutral observations become structured, attributable WorkItems.',url:'https://github.com/Aftergraph/work-intelligence-v2',maturity:'prototype',type:'product',icon:'I'},\n{group:'Build',name:'Knowledge Plane',purpose:'Developer and research portal compiled over canonical sources.',url:'https://docs.aftergraph.org',maturity:'public',type:'docs',icon:'D'},\n{group:'Build',name:'AIE',purpose:'Authority, delegation, revocation and institutional semantics.',url:'https://github.com/Aftergraph/aie',maturity:'prototype',type:'product',icon:'A'},\n{group:'Operate',name:'Trust Gateway',purpose:'Fail-closed approvals, policy, budgets and tamper-evident audit.',url:'https://github.com/Aftergraph/trust-gateway',maturity:'prototype',type:'product',icon:'T'},\n{group:'Operate',name:'Studio',purpose:'Operator surface for mission status, evidence and approvals.',url:'https://github.com/Aftergraph/studio',maturity:'prototype',type:'product',icon:'S'},\n{group:'Operate',name:'System status',purpose:'Operational snapshot for repositories, releases and platform routes.',url:'/status',maturity:'public',type:'docs',icon:'↗'},\n{group:'Verify',name:'Sentinel',purpose:'Exact-HEAD code review with evidence, verdicts and stale-base invalidation.',url:'https://github.com/Aftergraph/sentinel',maturity:'research',type:'research',icon:'V'},\n{group:'Verify',name:'Evidence and claim graph',purpose:'Explore provenance, claims and the boundary between evidence and authority.',url:'https://docs.aftergraph.org/evidence/',maturity:'public',type:'docs',icon:'E'},\n{group:'Research',name:'Intelligence Systems Research',purpose:'SPEC-001, MISSION-Bench, assurance and replication.',url:'https://github.com/Aftergraph/intelligence-systems-research',maturity:'research',type:'research',icon:'R'},\n{group:'Research',name:'Model Registry',purpose:'Model families, versions, lifecycle, provenance and evaluation records.',url:'https://github.com/Aftergraph/model-registry',maturity:'internal',type:'research',icon:'M'},\n{group:'Research',name:'Aftergraph Foundation Model',purpose:'Training, datasets, evaluations and adapters for agentic software engineering.',url:'https://github.com/Aftergraph/afm',maturity:'internal',type:'research',icon:'F'}\n];\nconst query=document.getElementById('q');const results=document.getElementById('results');const shell=document.getElementById('launcher-shell');let filtered=[];let active=0;\nfunction matches(item,text){return !text||text.split(/\\s+/).every(token=>`${item.group} ${item.name} ${item.purpose} ${item.maturity} ${item.type}`.toLowerCase().includes(token));}\nfunction setActive(next){const options=[...results.querySelectorAll('[role=\"option\"]')];if(!options.length){active=0;return}active=Math.max(0,Math.min(next,options.length-1));options.forEach((option,index)=>{const selected=index===active;option.classList.toggle('active',selected);option.setAttribute('aria-selected',String(selected));if(selected)option.scrollIntoView({block:'nearest'});});}\nfunction render(){const text=query.value.trim().toLowerCase();filtered=ITEMS.filter(item=>matches(item,text));active=0;if(!filtered.length){results.innerHTML='<div class=\"empty\"><strong>No destination found.</strong>Try “evidence”, “research” or “works”.</div>';return}let html='';let group='';filtered.forEach((item,index)=>{if(item.group!==group){html+=`<div class=\"group\">${item.group}</div>`;group=item.group}html+=`<a class=\"option\" id=\"option-${index}\" role=\"option\" aria-selected=\"${index===0}\" href=\"${item.url}\" data-index=\"${index}\"><span class=\"option-icon\" aria-hidden=\"true\">${item.icon}</span><span class=\"option-copy\"><span class=\"option-name\">${item.name}</span><span class=\"option-purpose\">${item.purpose}</span></span><span class=\"option-meta\"><span class=\"badge ${item.type}\">${item.maturity}</span><span class=\"arrow\" aria-hidden=\"true\">→</span></span></a>`});results.innerHTML=html;}\nresults.addEventListener('pointermove',event=>{const option=event.target.closest('[role=\"option\"]');if(option)setActive(Number(option.dataset.index));});\nquery.addEventListener('input',render);query.addEventListener('keydown',event=>{if(event.key==='ArrowDown'){event.preventDefault();setActive(active+1)}else if(event.key==='ArrowUp'){event.preventDefault();setActive(active-1)}else if(event.key==='Enter'){const option=results.querySelector('[aria-selected=\"true\"]');if(option)option.click()}else if(event.key==='Escape'){event.preventDefault();if(query.value){query.value='';render()}else{shell.focus()}}});\ndocument.addEventListener('keydown',event=>{if(event.key==='/'&&document.activeElement!==query&&document.activeElement?.tagName!=='INPUT'){event.preventDefault();query.focus()}});render();\n</script>\n</body>\n</html>\n";
